<?php

declare(strict_types=1);

/*
 * Filament's Indonesian translation renders the dashboard as "Dasbor".
 *
 * "Dashboard" is the loanword staff actually use — same reasoning that keeps
 * `surat jalan`, `faktur pajak` and `gudang` in Indonesian: use the word people
 * say, not the one a dictionary prefers. The rule cuts both ways.
 *
 * Laravel merges vendor overrides recursively, so only the changed key belongs
 * here.
 */

return [

    'title' => 'Dashboard',

];
